mapper.select:
SELECT LMS_PRF_ID
FROM LMS_PROFILE
WHERE MEMBER_ID = #{memberId}

mapper.insert:

    SELECT SEQ_LECTURE_ASSIGNMENT_SUBMISSION.NEXTVAL FROM dual

INSERT INTO LECTURE_ASSIGNMENT_SUBMISSION (
    LEC_ASN_SBM_ID, LEC_ASN_ID, LMS_PRF_ID,
    LEC_ASN_SBM_REG_DATE, LEC_ASN_SBM_STATUS, LEC_ASN_SBM_MEMO
) VALUES (
    #{submissionId}, #{assignmentId}, #{lmsPrfId},
    SYSTIMESTAMP, 'SBM', #{memo}
)

mapper.update:
UPDATE LECTURE_ASSIGNMENT_SUBMISSION
SET LEC_ASN_SBM_REG_DATE = SYSTIMESTAMP,
    LEC_ASN_SBM_STATUS = 'SBM',
    LEC_ASN_SBM_MEMO = #{memo}
WHERE LEC_ASN_SBM_ID = #{submissionId}
  AND LEC_ASN_SBM_STATUS = 'NSB'

UPDATE LECTURE_ASSIGNMENT_SUBMISSION
SET LEC_ASN_SBM_REG_DATE = SYSTIMESTAMP,
    LEC_ASN_SBM_MEMO = #{memo}
WHERE LEC_ASN_SBM_ID = #{submissionId}
  AND LEC_ASN_SBM_STATUS = 'SBM'
